import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.cart('a'), null);
  assert.deepEqual(await h.add('a'), { ok: false, reason: 'unknown' });
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.deepEqual(await h.cart('a'), { status: 'open', items: 0 });
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancelled while reserving gives back reserved units; paying cannot cancel', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.cancel('a');
  const [m] = await h.inFlight();
  await h.deliver(m.id);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'cancelled', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.open('b'); await h.add('b'); await h.checkout('b');
  await h.deliver((await h.inFlight())[0].id);
  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('b'))!.status, 'paying');
  assert.deepEqual(await h.cancel('b'), { ok: false, reason: 'payment-in-progress' });
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 1, declining: false });
});

test('declined, out of stock, cancelling', async () => {
  const h = await createHost();
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.acceptCards();
  await h.open('b'); await h.add('b'); await h.add('b'); await h.checkout('b');
  await h.open('c'); await h.add('c'); await h.checkout('c');
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.equal((await h.cart('c'))!.status, 'cancelling');
  await h.deliverAll();
  assert.equal((await h.cart('b'))!.status, 'paid');
  assert.equal((await h.cart('c'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  await h.open('d'); await h.add('d'); await h.checkout('d');
  await h.deliverAll();
  assert.equal((await h.cart('d'))!.status, 'failed');
  await h.open('e'); assert.deepEqual(await h.cancel('e'), { ok: true });
  assert.equal((await h.cart('e'))!.status, 'cancelled');
});

