        set('status', $.returned),
        send($.pay, 'Refund', { amount: $.items }),
        send($.inv, 'Release', { qty: $.items }),
      ]),
      on('Reserved', ($) => [
        require(isIn($.status, [$.reserving, $.cancelling]), 'not-reserving'),
        when($.status === $.reserving, [
          set('status', $.paying),
          send($.pay, 'Charge', { from: $.self, amount: $.items }),
