test('payment timeout', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a');
  assert.deepEqual(await h.paymentTimeout('a'), { ok: false, reason: 'not-paying' });
  await h.add('a'); await h.checkout('a');
  await h.deliver((await h.inFlight())[0].id); // Reserve
  await h.deliver((await h.inFlight())[0].id); // Reserved
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'abandoning');
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout', 'open'] as const) assert.equal((await h[cmd]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 2 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });

  await h.declineCards();
  await h.open('b'); await h.add('b'); await h.checkout('b');
  await h.deliver((await h.inFlight())[0].id);
  await h.deliver((await h.inFlight())[0].id);
  await h.paymentTimeout('b');
  await h.deliverAll();
  assert.deepEqual(await h.cart('b'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

